drop policy if exists "public can delete ingredients" on public.ingredients;
create policy "public can delete ingredients" on public.ingredients for delete using (exists(select 1 from public.households h where h.id=household_id and h.name='鍾家冰箱'));
drop policy if exists "public can create inventory" on public.inventory;
create policy "public can create inventory" on public.inventory for insert with check (exists(select 1 from public.ingredients i join public.households h on h.id=i.household_id where i.id=ingredient_id and h.name='鍾家冰箱'));
drop policy if exists "public can update inventory" on public.inventory;
create policy "public can update inventory" on public.inventory for update using (exists(select 1 from public.ingredients i join public.households h on h.id=i.household_id where i.id=ingredient_id and h.name='鍾家冰箱'));
drop policy if exists "public can create meals" on public.meals;
create policy "public can create meals" on public.meals for insert with check (exists(select 1 from public.households h where h.id=household_id and h.name='鍾家冰箱'));
drop policy if exists "public can update meals" on public.meals;
create policy "public can update meals" on public.meals for update using (exists(select 1 from public.households h where h.id=household_id and h.name='鍾家冰箱'));
drop policy if exists "public can create meal ingredients" on public.meal_ingredients;
create policy "public can create meal ingredients" on public.meal_ingredients for insert with check (exists(select 1 from public.meals m join public.households h on h.id=m.household_id where m.id=meal_id and h.name='鍾家冰箱'));
drop policy if exists "public can update meal ingredients" on public.meal_ingredients;
create policy "public can update meal ingredients" on public.meal_ingredients for update using (exists(select 1 from public.meals m join public.households h on h.id=m.household_id where m.id=meal_id and h.name='鍾家冰箱'));
